CREATE TYPE sync_status AS ENUM ('running','bounded_incomplete','completed','partial_failure','failed');
CREATE TABLE owner_binding (singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton), auth_user_id text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gmail_connection (owner_auth_user_id text PRIMARY KEY REFERENCES owner_binding(auth_user_id), google_subject text NOT NULL UNIQUE, encrypted_refresh_token text NOT NULL, key_version integer NOT NULL CHECK (key_version > 0), disconnected_at timestamptz, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE triage_config (id bigserial PRIMARY KEY, owner_auth_user_id text NOT NULL REFERENCES owner_binding(auth_user_id), version integer NOT NULL CHECK(version > 0), source_label_id text NOT NULL, priority_label_id text NOT NULL, review_label_id text NOT NULL, contest_label_id text NOT NULL, terms jsonb NOT NULL, sender_whitelist jsonb NOT NULL, bounds jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_auth_user_id, version));
CREATE TABLE sync_run (id uuid PRIMARY KEY, owner_auth_user_id text NOT NULL REFERENCES owner_binding(auth_user_id), config_version integer NOT NULL, status sync_status NOT NULL, next_page_token text, lease_owner text, lease_expires_at timestamptz, fence_token bigint NOT NULL DEFAULT 0, error_summary text, started_at timestamptz NOT NULL DEFAULT now(), finished_at timestamptz);
CREATE TABLE message_processing (run_id uuid NOT NULL REFERENCES sync_run(id), gmail_message_id text NOT NULL, gmail_thread_id text, internal_date timestamptz, sender_address text, subject text, label_ids jsonb, outcome text CHECK(outcome IN ('priority','review','new_contest','unmatched','protected','failed')), error_code text, processed_at timestamptz, PRIMARY KEY(run_id,gmail_message_id));
CREATE TABLE oauth_state (state_hash text PRIMARY KEY, owner_auth_user_id text NOT NULL, pkce_verifier_ciphertext text, expires_at timestamptz NOT NULL, consumed_at timestamptz);
CREATE INDEX sync_run_owner_started_idx ON sync_run(owner_auth_user_id, started_at DESC);
